import numpy as np, pandas as pd
from alphacrafter.sim.utils import get_stock_daily_data
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
def get(s):
 d=get_stock_daily_data(s,days=3000)
 if d is None:return pd.Series(dtype=float)
 return d.set_index('date')['close'].astype(float).sort_index()
px=pd.DataFrame({s:get(s) for s in U}); dxy=get('DXY'); r=px.pct_change(); dr=dxy.pct_change(); rows=[]; sigrows=[]
for dt in px.index:
 if dt not in dr.index:continue
 hist=r.loc[:dt].tail(60); dh=dr.loc[:dt].tail(60)
 if len(hist)<50 or len(dh)<50:continue
 d20=px.loc[:dt].pct_change(20).iloc[-1]; x=hist.fillna(0).values;y=dh.reindex(hist.index).fillna(0).values; den=np.sum((y-y.mean())**2)
 beta=((x-x.mean(0))*(y-y.mean())[:,None]).sum(0)/den if den>1e-12 else np.zeros(len(U)); sig=d20.values-beta*dxy.loc[:dt].pct_change(20)
 for s,v in zip(U,sig):sigrows.append({'date':dt,'symbol':s,'value':v})
 if dt in r.index:
  z=pd.DataFrame({'s':sig,'y':r.shift(-1).loc[dt].values}).dropna()
  if len(z)>=8:rows.append((dt,z.s.corr(z.y),len(z)))
a=pd.DataFrame(rows,columns=['date','ic','n']).set_index('date');print('dates',len(a),'mean_n',a.n.mean(),'mean_ic',a.ic.mean(),'icir',a.ic.mean()/a.ic.std(ddof=1),'hit',(a.ic>0).mean())
for y,g in a.groupby(a.index.year):print(y,len(g),round(g.ic.mean(),5),round(g.ic.mean()/g.ic.std(ddof=1),4))
pd.DataFrame(sigrows).to_csv('scripts/miner_1_20260730_dollar_residual_momentum_signals.csv',index=False);print('artifact rows',len(sigrows))

import pandas as pd, numpy as np, os
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
def ser(s):
 p=('../persistent/index_data/' if s=='DXY' else '../persistent/stock_data/')+s+'.csv'
 d=pd.read_csv(p,parse_dates=['date']).set_index('date').sort_index(); return d.close.astype(float)
px=pd.DataFrame({s:ser(s) for s in U}).join(ser('DXY').rename('DXY'),how='inner').sort_index()
r=px[U].pct_change(); dr=px.DXY.pct_change()
beta=r.rolling(60,min_periods=45).cov(dr).div(dr.rolling(60,min_periods=45).var(),axis=0)
f=r.rolling(20,min_periods=15).sum()-beta.mul(dr.rolling(20,min_periods=15).sum(),axis=0)
for h in [1,5,10]:
 vals=[]
 for i in range(len(px)-h):
  x=f.iloc[i]; y=(px[U].iloc[i+h]/px[U].iloc[i]-1); z=pd.concat([x,y],axis=1).dropna()
  if len(z)>=8: vals.append(z.iloc[:,0].corr(z.iloc[:,1]))
 a=np.array(vals); print('H',h,'dates',len(a),'IC',round(a.mean(),6),'ICIR',round(a.mean()/a.std(ddof=1),6),'hit',round((a>0).mean(),4))
valid=f.notna().sum(axis=1); print('coverage',valid.mean()/15,'mean names',valid.mean())
print('turnover',f.rank(axis=1,pct=True).diff().abs().mean(axis=1).dropna().mean())
for yr in range(2020,2027):
 a=[]
 for i in range(len(px)-1):
  if px.index[i].year!=yr: continue
  z=pd.concat([f.iloc[i],(px[U].iloc[i+1]/px[U].iloc[i]-1)],axis=1).dropna()
  if len(z)>=8:a.append(z.iloc[:,0].corr(z.iloc[:,1]))
 if a: print('REG',yr,len(a),round(np.mean(a),5),round(np.mean(a)/np.std(a,ddof=1),5))
print('period',px.index.min(),px.index.max(),'assets',len(U))

