import numpy as np,pandas as pd
from alphacrafter.sim.utils import get_stock_daily_data
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
px={}
for s in U:
 d=get_stock_daily_data(s,3000); d=d.copy();d.date=pd.to_datetime(d.date);px[s]=d.set_index('date').close
P=pd.DataFrame(px).sort_index(); r=P.pct_change(fill_method=None)
vol=r.rolling(20,min_periods=15).std(); med=vol.median(axis=1); f=vol.div(med,axis='index') * -1
fr=P.pct_change(fill_method=None).shift(-1)
ics=[]; ns=[]; dates=[]
for dt in f.index:
 z=pd.concat([f.loc[dt],fr.loc[dt]],axis=1).dropna()
 if len(z)>=8: dates.append(dt);ns.append(len(z));ics.append(z.iloc[:,0].corr(z.iloc[:,1],method='spearman'))
ic=pd.Series(ics,index=dates).dropna();print('DATES',len(ic),'AVG N',round(np.mean(ns),2),'coverage',round(f.notna().mean().mean(),4));print('IC',round(ic.mean(),6),'ICIR',round(ic.mean()/ic.std(),6),'hit',round((ic>0).mean(),4))
for y,g in ic.groupby(ic.index.year): print(y,len(g),round(g.mean(),5),round(g.mean()/g.std(),4))
print('turnover',round(f.rank(pct=True).diff().abs().mean().mean(),4))
